dashboard.definition:
{
  "title": "Wazuh - AWS - Agent dashboard",
  "description": "AWS - Agent dashboard of the Wazuh dashboard, on the findings exported from the Wazuh indexer. Pick the agent in the Agent input, as the Wazuh dashboard does.",
  "inputs": {
    "input_global_trp": {
      "type": "input.timerange",
      "title": "Time range",
      "options": {
        "token": "global_time",
        "defaultValue": "-24h@h,now"
      }
    },
    "input_scope": {
      "type": "input.dropdown",
      "title": "Agent",
      "dataSources": {
        "primary": "ds_input_01"
      },
      "options": {
        "items": ">frame(label, value) | prepend(formattedStatics) | objects()",
        "token": "scope",
        "defaultValue": "*"
      },
      "context": {
        "formattedConfig": {
          "number": {
            "prefix": ""
          }
        },
        "formattedStatics": ">statics | formatByType(formattedConfig)",
        "statics": [
          [
            "All"
          ],
          [
            "*"
          ]
        ],
        "label": ">primary | seriesByName(\"label\") | renameSeries(\"label\") | formatByType(formattedConfig)",
        "value": ">primary | seriesByName(\"value\") | renameSeries(\"value\") | formatByType(formattedConfig)"
      }
    }
  },
  "defaults": {
    "dataSources": {
      "ds.search": {
        "options": {
          "queryParameters": {
            "earliest": "$global_time.earliest$",
            "latest": "$global_time.latest$"
          }
        }
      }
    }
  },
  "dataSources": {
    "ds_input_01": {
      "type": "ds.search",
      "name": "Agent",
      "options": {
        "query": "`wazuh_findings` \"wazuh.integration.name\"=\"aws*\" \"wazuh.agent.name\"=* | eval value='wazuh.agent.name' | stats count by value | sort - count | head 500 | eval label=value | fields label, value"
      }
    },
    "ds_01": {
      "type": "ds.search",
      "name": "Top 5 sources (agent)",
      "options": {
        "query": "`wazuh_findings` \"wazuh.integration.name\"=\"aws*\" \"wazuh.agent.name\"=$scope|s$ | eval f1='event.provider' | stats count as metric by f1 | sort - metric | head 5 | rename f1 as \"event.provider\", metric as \"Count\""
      }
    },
    "ds_02": {
      "type": "ds.search",
      "name": "Top 5 accounts (agent)",
      "options": {
        "query": "`wazuh_findings` \"wazuh.integration.name\"=\"aws*\" \"wazuh.agent.name\"=$scope|s$ | eval f1='cloud.account.id' | stats count as metric by f1 | sort - metric | head 5 | rename f1 as \"cloud.account.id\", metric as \"Count\""
      }
    },
    "ds_03": {
      "type": "ds.search",
      "name": "Top 5 actions (agent)",
      "options": {
        "query": "`wazuh_findings` \"wazuh.integration.name\"=\"aws*\" \"wazuh.agent.name\"=$scope|s$ | eval f1='event.action' | stats count as metric by f1 | sort - metric | head 5 | rename f1 as \"event.action\", metric as \"Count\""
      }
    },
    "ds_04": {
      "type": "ds.search",
      "name": "Top 5 AWS regions (agent)",
      "options": {
        "query": "`wazuh_findings` \"wazuh.integration.name\"=\"aws*\" \"wazuh.agent.name\"=$scope|s$ | eval f1='cloud.region' | stats count as metric by f1 | sort - metric | head 5 | rename f1 as \"cloud.region\", metric as \"Count\""
      }
    },
    "ds_05": {
      "type": "ds.search",
      "name": "Events by source over time (agent)",
      "options": {
        "query": "`wazuh_findings` \"wazuh.integration.name\"=\"aws*\" \"wazuh.agent.name\"=$scope|s$ | eval f1='event.provider' | timechart useother=f usenull=f limit=5 count by f1"
      }
    },
    "ds_06": {
      "type": "ds.search",
      "name": "Top actions over time (agent)",
      "options": {
        "query": "`wazuh_findings` \"wazuh.integration.name\"=\"aws*\" \"wazuh.agent.name\"=$scope|s$ | eval f1='event.action' | timechart useother=f usenull=f limit=5 count by f1"
      }
    },
    "ds_07": {
      "type": "ds.search",
      "name": "Top Source IPs and Actions (agent)",
      "options": {
        "query": "`wazuh_findings` \"wazuh.integration.name\"=\"aws*\" \"wazuh.agent.name\"=$scope|s$ | eval f1='source.ip', f2='event.action', f3='cloud.account.id' | stats count as metric by f1, f2, f3 | sort - metric | head 225 | rename f1 as \"Source IP\", f2 as \"Top Actions\", f3 as \"Account ID\", metric as \"Event Count\""
      }
    }
  },
  "visualizations": {
    "viz_01": {
      "type": "splunk.pie",
      "title": "Top 5 sources (agent)",
      "dataSources": {
        "primary": "ds_01"
      },
      "options": {
        "showDonutHole": true
      }
    },
    "viz_02": {
      "type": "splunk.pie",
      "title": "Top 5 accounts (agent)",
      "dataSources": {
        "primary": "ds_02"
      },
      "options": {
        "showDonutHole": true
      }
    },
    "viz_03": {
      "type": "splunk.pie",
      "title": "Top 5 actions (agent)",
      "dataSources": {
        "primary": "ds_03"
      },
      "options": {
        "showDonutHole": true
      }
    },
    "viz_04": {
      "type": "splunk.pie",
      "title": "Top 5 AWS regions (agent)",
      "dataSources": {
        "primary": "ds_04"
      },
      "options": {
        "showDonutHole": true
      }
    },
    "viz_05": {
      "type": "splunk.area",
      "title": "Events by source over time (agent)",
      "dataSources": {
        "primary": "ds_05"
      },
      "options": {
        "stackMode": "stacked"
      }
    },
    "viz_06": {
      "type": "splunk.area",
      "title": "Top actions over time (agent)",
      "dataSources": {
        "primary": "ds_06"
      },
      "options": {
        "stackMode": "stacked"
      }
    },
    "viz_07": {
      "type": "splunk.table",
      "title": "Top Source IPs and Actions (agent)",
      "dataSources": {
        "primary": "ds_07"
      },
      "options": {}
    }
  },
  "layout": {
    "type": "absolute",
    "options": {
      "width": 1200,
      "height": 836,
      "display": "auto-scale"
    },
    "globalInputs": [
      "input_global_trp",
      "input_scope"
    ],
    "structure": [
      {
        "item": "viz_01",
        "type": "block",
        "position": {
          "x": 0,
          "y": 0,
          "w": 296,
          "h": 176
        }
      },
      {
        "item": "viz_02",
        "type": "block",
        "position": {
          "x": 300,
          "y": 0,
          "w": 296,
          "h": 176
        }
      },
      {
        "item": "viz_03",
        "type": "block",
        "position": {
          "x": 600,
          "y": 0,
          "w": 296,
          "h": 176
        }
      },
      {
        "item": "viz_04",
        "type": "block",
        "position": {
          "x": 900,
          "y": 0,
          "w": 296,
          "h": 176
        }
      },
      {
        "item": "viz_05",
        "type": "block",
        "position": {
          "x": 0,
          "y": 180,
          "w": 596,
          "h": 236
        }
      },
      {
        "item": "viz_06",
        "type": "block",
        "position": {
          "x": 600,
          "y": 180,
          "w": 596,
          "h": 236
        }
      },
      {
        "item": "viz_07",
        "type": "block",
        "position": {
          "x": 0,
          "y": 420,
          "w": 1196,
          "h": 396
        }
      }
    ]
  }
}
